mapper.sql:
unique_device_contracts AS (
SELECT c.id, c.tenant_id, c.contract_no, c.company_code, c.company_id, c.department_code FROM com_contract c JOIN device_filter_contract_keys k ON c.contract_no = CONVERT(k.contract_key USING utf8mb4) COLLATE utf8mb4_0900_ai_ci AND k.contract_key = CAST(c.contract_no AS BINARY) WHERE c.tenant_id = #{query.tenantId} AND c.deleted = b'0'
AND NOT EXISTS ( SELECT 1 FROM com_contract duplicate_contract WHERE duplicate_contract.tenant_id = c.tenant_id AND duplicate_contract.deleted = b'0' AND duplicate_contract.contract_no = c.contract_no AND duplicate_contract.id <> c.id )
SELECT MAX(id) AS id, MAX(tenant_id) AS tenant_id, contract_no, MAX(company_code) AS company_code, MAX(company_id) AS company_id, MAX(department_code) AS department_code FROM com_contract WHERE tenant_id = #{query.tenantId} AND deleted = b'0' GROUP BY contract_no HAVING COUNT(*) = 1
), device_contract_organization_rows AS ( SELECT c.contract_no, c.company_id, c.company_code, NULL AS department_id, c.department_code FROM unique_device_contracts c UNION ALL SELECT s.contract_no, s.company_id, s.company_code, s.department_id, s.department_code FROM com_shipment_contract_reference s JOIN unique_device_contracts c ON c.contract_no = s.contract_no AND c.tenant_id = s.tenant_id WHERE s.tenant_id = #{query.tenantId} AND s.deleted = b'0' ), device_contract_organizations AS ( SELECT contract_no, MAX(company_id) AS company_id, CASE WHEN COUNT(DISTINCT NULLIF(department_code, '')) = 1 THEN MAX(department_id) END AS department_id, CASE WHEN COUNT(DISTINCT NULLIF(department_code, '')) = 1 THEN MAX(NULLIF(department_code, '')) END AS department_code FROM device_contract_organization_rows GROUP BY contract_no HAVING COUNT(DISTINCT company_id) = 1 AND COUNT(DISTINCT NULLIF(company_code, '')) = 1 AND SUM(CASE WHEN company_code IS NULL OR company_code = '' THEN 1 ELSE 0 END) = 0 ), visible_device_contracts AS ( SELECT DISTINCT CAST(c.contract_no AS BINARY) AS contract_key FROM unique_device_contracts c JOIN device_contract_organizations organization ON organization.contract_no = c.contract_no WHERE c.tenant_id = #{query.tenantId} AND c.contract_no IS NOT NULL AND c.contract_no <> '' AND 1 = 0 AND NOT EXISTS ( SELECT 1 FROM com_shipment_contract_reference shipment WHERE shipment.tenant_id = c.tenant_id AND shipment.deleted = b'0' AND shipment.contract_no = c.contract_no AND (shipment.company_code IS NULL OR shipment.company_code = '' OR CAST(shipment.company_code AS BINARY) <> CAST(c.company_code AS BINARY)) ) AND (
(organization.company_id = #{grant.companyId}
AND (organization.department_id = #{grant.departmentId}
OR CAST(organization.department_code AS BINARY) = CAST(#{grant.departmentCode} AS BINARY) ) ) OR
1 = 0 ) )
